INSERT INTO bauth.bos_crypto_algorithm VALUES ('argon2id', 'Argon2id', 'hashing', 'classical', 'Password hashing (NIST SP 800-63B)', '{"memory_kb": 131072, "hash_bytes": 32, "iterations": 3, "salt_bytes": 16, "parallelism": 2}', NULL, NULL, '{NIST_800-63B_Rev4,RFC_9106}', true, true, '2026-06-21 18:58:18.923382+00') ON CONFLICT DO NOTHING;
