INSERT INTO bauth.bos_crypto_algorithm VALUES ('aes_256_gcm', 'AES-256-GCM', 'encryption', 'classical', 'Encryption at rest (cache, offline creds, biometric templates)', '{"key_bytes": 32, "tag_bytes": 16, "nonce_bytes": 12}', 'FIPS_140-3_certified', NULL, '{FIPS_197,NIST_SP_800-38D}', true, true, '2026-06-21 18:58:18.923382+00') ON CONFLICT DO NOTHING;
